// Runs before `npm pack` / `npm publish` (package.json "prepack").
// The compiled template compiler (rust-compiler/pkg) is gitignored and regenerated by wasm-pack,
// whose pkg/.gitignore excludes everything. Re-create the pkg/.npmignore that lets npm publish it,
// and refuse to pack without the wasm: every template compile depends on it.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const pkgDir = path.join(root, 'framework/core/rust-compiler/pkg')
const wasm = path.join(pkgDir, 'fusee_compiler_bg.wasm')

if (!fs.existsSync(wasm)) {
    console.error('[prepack] Missing framework/core/rust-compiler/pkg/fusee_compiler_bg.wasm.')
    console.error('[prepack] Build it first: cd framework/core/rust-compiler && wasm-pack build --release')
    process.exit(1)
}

fs.writeFileSync(path.join(pkgDir, '.npmignore'), "# Generated by scripts/prepack.mjs: wasm-pack's .gitignore would hide pkg/ from npm.\n")
console.log('[prepack] Compiler wasm found; pkg/ will be published.')
